INSERT INTO `task_logglue` (`id`, `job_id`, `glue_type`, `glue_source`, `glue_remark`, `create_time`, `update_time`) VALUES (1, 77, 'GLUE_GROOVY', 'package com.xxl.job.service.handler;\n\nimport com.xxl.job.core.context.XxlJobHelper;\nimport com.xxl.job.core.handler.IJobHandler;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport com.xxl.job.executor.service.jobhandler.TestService;\npublic class DemoGlueJobHandler extends IJobHandler {\n  \n   @Autowired\n    private TestService testService; \n\n	@Override\n	public void execute() throws Exception {\n		XxlJobHelper.log(\"XXL-JOB, Hello World.\");\n      testService.test1();\n	}\n\n}\n', 'testGlue', NULL, NULL);
